}

String _headerForField(String name, String value) {
  var header =
      'content-disposition: form-data; name="${_browserEncode(name)}"';
  if (!isPlainAscii(value)) {
    header = '$header\r\n'
        'content-type: text/plain; charset=utf-8\r\n'
        'content-transfer-encoding: binary';
  }
  return '$header\r\n\r\n';
}

int readInteger(int prefixBits) {
  assert(prefixBits <= 8 && prefixBits > 0);

  var byte = data[offset++] & ((1 << prefixBits) - 1);

  int integer;
  if (byte == ((1 << prefixBits) - 1)) {
    // Length encodeded.
    integer = 0;
    var shift = 0;
    while (true) {
      var done = (data[offset] & 0x80) != 0x80;
      integer += (data[offset++] & 0x7f) << shift;
      shift += 7;
      if (done) break;
    }
    integer += (1 << prefixBits) - 1;
  } else {
    // In place length.
    integer = byte;
  }

  return integer;
}

Map<String, List<String>> splitHeaderValues(Map<String, String> headers) {
  var headersWithFieldLists = <String, List<String>>{};
  headers.forEach((key, value) {
    if (!value.contains(',')) {
      headersWithFieldLists[key] = [value];
    } else {
      if (key == 'set-cookie') {
        headersWithFieldLists[key] = value.split(_setCookieSplitter);
      } else {
        headersWithFieldLists[key] = value.split(_headerSplitter);
      }
    }
  });
  return headersWithFieldLists;
}

int _digitForByte(List<int> bytes, int index) {
  // If the byte is a numeral, get its value. XOR works because 0 in ASCII is
  // `0b110000` and the other numerals come after it in ascending order and
  // take up at most four bits.
  //
  // We check for digits first because it ensures there's only a single branch
  // for 10 out of 16 of the expected cases. We don't count the `digit >= 0`
  // check because branch prediction will always work on it for valid data.
  final byte = bytes[index];
  final digit = $0 ^ byte;
  if (digit <= 9) {
    if (digit >= 0) return digit;
  } else {
    // If the byte is an uppercase letter, convert it to lowercase. This works
    // because uppercase letters in ASCII are exactly `0b100000 = 0x20` less
    // than lowercase letters, so if we ensure that that bit is 1 we ensure
    // that the letter is lowercase.
    final letter = 0x20 | byte;
    if ($a <= letter && letter <= $f) return letter - $a + 10;
  }

  throw FormatException(
      'Invalid hexadecimal byte 0x${byte.toRadixString(16).toUpperCase()}.',
      bytes,
      index);
}

List<int> _convert(List<int> bytes, int start, int end, {bool isLast = false}) {
  if (end == start) return isLast ? _doneChunk : const [];

  final size = end - start;
  final sizeInHex = size.toRadixString(16);
  final footerSize = isLast ? _doneChunk.length : 0;

  // Add 4 for the CRLF sequences that follow the size header and the bytes.
  final list = Uint8List(sizeInHex.length + 4 + size + footerSize);
  list.setRange(0, sizeInHex.length, sizeInHex.codeUnits);

  var cursor = sizeInHex.length;
  list[cursor++] = $cr;
  list[cursor++] = $lf;
  list.setRange(cursor, cursor + end - start, bytes, start);
  cursor += end - start;
  list[cursor++] = $cr;
  list[cursor++] = $lf;

  if (isLast) {
    list.setRange(list.length - footerSize, list.length, _doneChunk);
  }
  return list;
}

ByteStream finalize() {
  // TODO: freeze fields and files
  final boundary = _boundaryString();
  headers['content-type'] = 'multipart/form-data; boundary=$boundary';
  super.finalize();
  return ByteStream(_finalize(boundary));
}

FrameHeader _readFrameHeader(List<int> bytes, int offset) {
  var length = readInt24(bytes, offset);
  var type = bytes[offset + 3];
  var flags = bytes[offset + 4];
  var streamId = readInt32(bytes, offset + 5) & 0x7fffffff;

  return FrameHeader(length, type, flags, streamId);
}

void _reduce() {
  while (_currentSize > _maximumSize) {
    var h = _dynamicTable.removeLast();
    _currentSize -= _sizeOf(h);
  }
}

String _headerForFile(MultipartFile file) {
  var header = 'content-type: ${file.contentType}\r\n'
      'content-disposition: form-data; name="${_browserEncode(file.field)}"';

  if (file.filename != null) {
    header = '$header; filename="${_browserEncode(file.filename!)}"';
  }
  return '$header\r\n\r\n';
}

Header readHeaderFieldInternal(int index, {bool neverIndexed = false}) {
  List<int> name, value;
  if (index > 0) {
    name = _table.lookup(index).name;
    value = readStringLiteral();
  } else {
    name = readStringLiteral();
    value = readStringLiteral();
  }
  return Header(name, value, neverIndexed: neverIndexed);
}

void _close([List<int>? chunk, int? index]) {
  if (_state != _State.end) {
    throw FormatException('Input ended unexpectedly.', chunk, index);
  }

  _sink.close();
}

void _mergeLists(List<List<int>> bufferedData, int numberOfBytes) {
  if (bufferedData[0].length < numberOfBytes) {
    var numLists = 0;
    var accumulatedLength = 0;
    while (accumulatedLength < numberOfBytes &&
        numLists <= bufferedData.length) {
      accumulatedLength += bufferedData[numLists++].length;
    }
    assert(accumulatedLength >= numberOfBytes);
    var newList = Uint8List(accumulatedLength);
    var offset = 0;
    for (var i = 0; i < numLists; i++) {
      var data = bufferedData[i];
      newList.setRange(offset, offset + data.length, data);
      offset += data.length;
    }
    bufferedData[0] = newList;
    bufferedData.removeRange(1, numLists);
  }
}

StreamedRequest _copyRequest(BaseRequest original, Stream<List<int>> body) {
  final StreamedRequest request;
  if (original case Abortable(:final abortTrigger?)) {
    request = AbortableStreamedRequest(
      original.method,
      original.url,
      abortTrigger: abortTrigger,
    );
  } else {
    request = StreamedRequest(original.method, original.url);
  }

  request
    ..contentLength = original.contentLength
    ..followRedirects = original.followRedirects
    ..headers.addAll(original.headers)
    ..maxRedirects = original.maxRedirects
    ..persistentConnection = original.persistentConnection;

  body.listen(request.sink.add,
      onError: request.sink.addError,
      onDone: request.sink.close,
      cancelOnError: true);

  return request;
}

String _boundaryString() {
  var prefix = 'dart-http-boundary-';
  var list = List<int>.generate(
      _boundaryLength - prefix.length,
      (index) =>
          boundaryCharacters[_random.nextInt(boundaryCharacters.length)],
      growable: false);
  return '$prefix${String.fromCharCodes(list)}';
}

void writeInteger(int prefixBits, int value) {
  assert(prefixBits <= 8);

  if (value < (1 << prefixBits) - 1) {
    currentByte |= value;
    bytesBuilder.addByte(currentByte);
  } else {
    // Length encodeded.
    currentByte |= (1 << prefixBits) - 1;
    value -= (1 << prefixBits) - 1;
    bytesBuilder.addByte(currentByte);
    var done = false;
    while (!done) {
      currentByte = value & 0x7f;
      value = value >> 7;
      done = value == 0;
      if (!done) currentByte |= 0x80;
      bytesBuilder.addByte(currentByte);
    }
  }
  currentByte = 0;
}

std::string message(int error_code) const override {
  auto&& msg = system_message(error_code);
  if (msg) {
    auto utf8_message = fmt::detail::to_utf8<wchar_t>();
    if (utf8_message.convert(msg)) {
      return utf8_message.str();
    }
  }
  return "unknown error";
}

