def loop_last(values: Iterable[T]) -> Iterable[Tuple[bool, T]]:
    """Iterate and generate a tuple with a flag for last value."""
    iter_values = iter(values)
    try:
        previous_value = next(iter_values)
    except StopIteration:
        return
    for value in iter_values:
        yield False, previous_value
        previous_value = value
    yield True, previous_value

def _emoji_replace(
    text: str,
    default_variant: Optional[str] = None,
    _emoji_sub: _EmojiSubMethod = re.compile(r"(:(\S*?)(?:(?:\-)(emoji|text))?:)").sub,
) -> str:
    """Replace emoji code in text."""
    from ._emoji_codes import EMOJI

    get_emoji = EMOJI.__getitem__
    variants = {"text": "\ufe0e", "emoji": "\ufe0f"}
    get_variant = variants.get
    default_variant_code = variants.get(default_variant, "") if default_variant else ""

    def do_replace(match: Match[str]) -> str:
        emoji_code, emoji_name, variant = match.groups()
        try:
            return get_emoji(emoji_name.lower()) + get_variant(
                variant, default_variant_code
            )
        except KeyError:
            return emoji_code

    return _emoji_sub(do_replace, text)

def get_file(f):
    try:
        return open(os.path.basename(f))
    except FileNotFoundError:
        subprocess.run(["curl", "-O", f], check=True)
        return open(os.path.basename(f))

def _iter_syntax_lines(
    start: SyntaxPosition, end: SyntaxPosition
) -> Iterable[Tuple[int, int, int]]:
    """Yield start and end positions per line.

    Args:
        start: Start position.
        end: End position.

    Returns:
        Iterable of (LINE, COLUMN1, COLUMN2).
    """

    line1, column1 = start
    line2, column2 = end

    if line1 == line2:
        yield line1, column1, column2
    else:
        for first, last, line_no in loop_first_last(range(line1, line2 + 1)):
            if first:
                yield line_no, column1, -1
            elif last:
                yield line_no, 0, column2
            else:
                yield line_no, 0, -1

def set_cell_size(text: str, total: int, unicode_version: str = "auto") -> str:
    """Adjust a string by cropping or padding with spaces such that it fits within the given number of cells.

    Args:
        text: String to adjust.
        total: Desired size in cells.
        unicode_version: Unicode version.

    Returns:
        A string with cell size equal to total.
    """
    if _is_single_cell_widths(text):
        size = len(text)
        if size < total:
            return text + " " * (total - size)
        return text[:total]
    if total <= 0:
        return ""
    cell_size = cell_len(text)
    if cell_size == total:
        return text
    if cell_size < total:
        return text + " " * (total - cell_size)
    text, _ = _split_text(text, total, unicode_version)
    return text

def load(unicode_version: str = "auto") -> CellTable:
    """Load a cell table for the given unicode version.

    Args:
        unicode_version: Unicode version, or `None` to auto-detect.

    """
    if unicode_version == "auto":
        unicode_version = os.environ.get("UNICODE_VERSION", "latest")
        try:
            _parse_version(unicode_version)
        except ValueError:
            # The environment variable is invalid
            # Fallback to using the latest version seems reasonable
            unicode_version = "latest"

    if unicode_version == "latest":
        version = VERSIONS[-1]
    else:
        try:
            version_numbers = _parse_version(unicode_version)
        except ValueError:
            version_numbers = _parse_version(VERSIONS[-1])
        major, minor, patch = version_numbers
        version = f"{major}.{minor}.{patch}"
        if version not in VERSION_SET:
            insert_position = bisect.bisect_left(VERSION_ORDER, version_numbers)
            version = VERSIONS[max(0, insert_position - 1)]

    version_path_component = version.replace(".", "-")
    module_name = f".unicode{version_path_component}"
    module = import_module(module_name, "rich._unicode_data")
    if TYPE_CHECKING:
        assert isinstance(module.cell_table, CellTable)
    return module.cell_table

def pick_bool(*values: Optional[bool]) -> bool:
    """Pick the first non-none bool or return the last value.

    Args:
        *values (bool): Any number of boolean or None values.

    Returns:
        bool: First non-none boolean.
    """
    assert values, "1 or more values required"
    for value in values:
        if value is not None:
            return value
    return bool(value)

private static JsonElement fromValue(Value value) {
  switch (value.getKindCase()) {
    case NUMBER_VALUE:
      double number = value.getNumberValue();
      if (Double.isNaN(number) || Double.isInfinite(number)) {
        throw new IllegalArgumentException(
            "Struct contains a NaN or Infinite number value, which has no JSON representation: "
                + number);
      }
      return new JsonPrimitive(number);
    case STRING_VALUE:
      return new JsonPrimitive(value.getStringValue());
    case BOOL_VALUE:
      return new JsonPrimitive(value.getBoolValue());
    case STRUCT_VALUE:
      return fromStruct(value.getStructValue());
    case LIST_VALUE:
      return fromListValue(value.getListValue());
    case NULL_VALUE:
    case KIND_NOT_SET:
      return JsonNull.INSTANCE;
  }
  throw new AssertionError("Unreachable: " + value.getKindCase());
}

private List<String> splitPackages(String packagesString) {
  List<String> splitPackages = new ArrayList<>();
  int nextSplitStart = 0;
  boolean isInQuotes = false;

  for (int i = 0; i < packagesString.length(); i++) {
    char c = packagesString.charAt(i);
    // Ignore ',' inside quotes
    if (c == '"') {
      isInQuotes = !isInQuotes;
    } else if (c == ',' && !isInQuotes) {
      splitPackages.add(packagesString.substring(nextSplitStart, i));
      nextSplitStart = i + 1; // skip past the ','
    }
  }

  // Add package behind last ','
  splitPackages.add(packagesString.substring(nextSplitStart));
  return splitPackages;
}

public boolean isAssignableFrom(Type from) {
  if (from == null) {
    return false;
  }

  if (type.equals(from)) {
    return true;
  }

  if (type instanceof Class<?>) {
    return rawType.isAssignableFrom(GsonTypes.getRawType(from));
  } else if (type instanceof ParameterizedType) {
    return isAssignableFrom(from, (ParameterizedType) type, new HashMap<String, Type>());
  } else if (type instanceof GenericArrayType) {
    return rawType.isAssignableFrom(GsonTypes.getRawType(from))
        && isAssignableFrom(from, (GenericArrayType) type);
  } else {
    throw buildUnsupportedTypeException(
        type, Class.class, ParameterizedType.class, GenericArrayType.class);
  }
}

private static void verifyNoTypeVariable(Type type) {
  if (type instanceof TypeVariable) {
    TypeVariable<?> typeVariable = (TypeVariable<?>) type;
    throw new IllegalArgumentException(
        "TypeToken type argument must not contain a type variable; captured type variable "
            + typeVariable.getName()
            + " declared by "
            + typeVariable.getGenericDeclaration()
            + "\nSee "
            + TroubleshootingGuide.createUrl("typetoken-type-variable"));
  } else if (type instanceof GenericArrayType) {
    verifyNoTypeVariable(((GenericArrayType) type).getGenericComponentType());
  } else if (type instanceof ParameterizedType) {
    ParameterizedType parameterizedType = (ParameterizedType) type;
    Type ownerType = parameterizedType.getOwnerType();
    if (ownerType != null) {
      verifyNoTypeVariable(ownerType);
    }

    for (Type typeArgument : parameterizedType.getActualTypeArguments()) {
      verifyNoTypeVariable(typeArgument);
    }
  } else if (type instanceof WildcardType) {
    WildcardType wildcardType = (WildcardType) type;
    for (Type bound : wildcardType.getLowerBounds()) {
      verifyNoTypeVariable(bound);
    }
    for (Type bound : wildcardType.getUpperBounds()) {
      verifyNoTypeVariable(bound);
    }
  } else if (type == null) {
    // Occurs in Eclipse IDE and certain Java versions (e.g. Java 11.0.18) when capturing type
    // variable declared by method of local class, see
    // https://github.com/eclipse-jdt/eclipse.jdt.core/issues/975
    throw new IllegalArgumentException(
        "TypeToken captured `null` as type argument; probably a compiler / runtime bug");
  }
}

String[] getRecordComponentNames(Class<?> raw) {
  try {
    Object[] recordComponents = (Object[]) getRecordComponents.invoke(raw);
    String[] componentNames = new String[recordComponents.length];
    for (int i = 0; i < recordComponents.length; i++) {
      componentNames[i] = (String) getName.invoke(recordComponents[i]);
    }
    return componentNames;
  } catch (ReflectiveOperationException e) {
    throw createExceptionForRecordReflectionException(e);
  }
}

