      .splitToStream(versionString)
      .limit(keepPosition + 1)
      .collect(Collectors.joining("."));
}

private static JsonArray fromListValue(ListValue listValue) {
  JsonArray array = new JsonArray();
  for (Value value : listValue.getValuesList()) {
    array.add(fromValue(value));
  }
  return array;
}

private static boolean isAssignableFrom(Type from, GenericArrayType to) {
  Type toGenericComponentType = to.getGenericComponentType();
  if (toGenericComponentType instanceof ParameterizedType) {
    Type t = from;
    if (from instanceof GenericArrayType) {
      t = ((GenericArrayType) from).getGenericComponentType();
    } else if (from instanceof Class<?>) {
      Class<?> classType = (Class<?>) from;
      while (classType.isArray()) {
        classType = classType.getComponentType();
      }
      t = classType;
    }
    return isAssignableFrom(
        t, (ParameterizedType) toGenericComponentType, new HashMap<String, Type>());
  }
  // No generic defined on "to"; therefore, return true and let other
  // checks determine assignability
  return true;
}

public static String tryMakeAccessible(Constructor<?> constructor) {
  try {
    constructor.setAccessible(true);
    return null;
  } catch (Exception exception) {
    return "Failed making constructor '"
        + constructorToString(constructor)
        + "' accessible; either increase its visibility or write a custom InstanceCreator or"
        + " TypeAdapter for its declaring type: "
        // Include the message since it might contain more detailed information
        + exception.getMessage()
        + getInaccessibleTroubleshootingSuffix(exception);
  }
}

private String keyToString(JsonElement keyElement) {
  if (keyElement.isJsonPrimitive()) {
    JsonPrimitive primitive = keyElement.getAsJsonPrimitive();
    if (primitive.isNumber()) {
      return String.valueOf(primitive.getAsNumber());
    } else if (primitive.isBoolean()) {
      return Boolean.toString(primitive.getAsBoolean());
    } else if (primitive.isString()) {
      return primitive.getAsString();
    } else {
      throw new AssertionError();
    }
  } else if (keyElement.isJsonNull()) {
    return "null";
  } else {
    throw new AssertionError();
  }
}

private static int indexOfNonDigit(String string, int offset) {
  for (int i = offset; i < string.length(); i++) {
    char c = string.charAt(i);
    if (c < '0' || c > '9') {
      return i;
    }
  }
  return string.length();
}

public static String format(Date date, boolean millis, TimeZone tz) {
  Calendar calendar = new GregorianCalendar(tz, Locale.US);
  calendar.setTime(date);

  // estimate capacity of buffer as close as we can (yeah, that's pedantic ;)
  int capacity = "yyyy-MM-ddThh:mm:ss".length();
  capacity += millis ? ".sss".length() : 0;
  capacity += tz.getRawOffset() == 0 ? "Z".length() : "+hh:mm".length();
  StringBuilder formatted = new StringBuilder(capacity);

  padInt(formatted, calendar.get(Calendar.YEAR), "yyyy".length());
  formatted.append('-');
  padInt(formatted, calendar.get(Calendar.MONTH) + 1, "MM".length());
  formatted.append('-');
  padInt(formatted, calendar.get(Calendar.DAY_OF_MONTH), "dd".length());
  formatted.append('T');
  padInt(formatted, calendar.get(Calendar.HOUR_OF_DAY), "hh".length());
  formatted.append(':');
  padInt(formatted, calendar.get(Calendar.MINUTE), "mm".length());
  formatted.append(':');
  padInt(formatted, calendar.get(Calendar.SECOND), "ss".length());
  if (millis) {
    formatted.append('.');
    padInt(formatted, calendar.get(Calendar.MILLISECOND), "sss".length());
  }

  int offset = tz.getOffset(calendar.getTimeInMillis());
  if (offset != 0) {
    int hours = Math.abs((offset / (60 * 1000)) / 60);
    int minutes = Math.abs((offset / (60 * 1000)) % 60);
    formatted.append(offset < 0 ? '-' : '+');
    padInt(formatted, hours, "hh".length());
    formatted.append(':');
    padInt(formatted, minutes, "mm".length());
  } else {
    formatted.append('Z');
  }

  return formatted.toString();
}

private Type getTypeTokenTypeArgument() {
  Type superclass = getClass().getGenericSuperclass();
  if (superclass instanceof ParameterizedType) {
    ParameterizedType parameterized = (ParameterizedType) superclass;
    if (parameterized.getRawType() == TypeToken.class) {
      Type typeArgument = GsonTypes.canonicalize(parameterized.getActualTypeArguments()[0]);

      if (isCapturingTypeVariablesForbidden()) {
        verifyNoTypeVariable(typeArgument);
      }
      return typeArgument;
    }
  }
  // Check for raw TypeToken as superclass
  else if (superclass == TypeToken.class) {
    throw new IllegalStateException(
        "TypeToken must be created with a type argument: new TypeToken<...>() {}; When using code"
            + " shrinkers (ProGuard, R8, ...) make sure that generic signatures are preserved."
            + "\nSee "
            + TroubleshootingGuide.createUrl("type-token-raw"));
  }

  // User created subclass of subclass of TypeToken
  throw new IllegalStateException("Must only create direct subclasses of TypeToken");
}

private static String getInaccessibleTroubleshootingSuffix(Exception e) {
  // Class was added in Java 9, therefore cannot use instanceof
  if (e.getClass().getName().equals("java.lang.reflect.InaccessibleObjectException")) {
    String message = e.getMessage();
    String troubleshootingId =
        message != null && message.contains("to module com.google.gson")
            ? "reflection-inaccessible-to-module-gson"
            : "reflection-inaccessible";
    return "\nSee " + TroubleshootingGuide.createUrl(troubleshootingId);
  }
  return "";
}

private String increaseVersionNumber(String versionString, int position) {
  List<Integer> splitVersion = new ArrayList<>();
  for (String versionPiece : Splitter.on('.').split(versionString)) {
    splitVersion.add(Integer.valueOf(versionPiece));
  }
  // Drop lower version parts
  splitVersion = splitVersion.subList(0, position + 1);
  // Increase version number
  splitVersion.set(position, splitVersion.get(position) + 1);

  return splitVersion.stream().map(i -> i.toString()).collect(Collectors.joining("."));
}

