function throwErrorForPartIndexMismatch(
  partIndex: number,
  result: TemplateResult
) {
  const errorMsg = `
    Unexpected final partIndex: ${partIndex} !== ${
      result.values.length
    } while processing the following template:

    ${displayTemplateResult(result)}

    This could be because you're attempting to render an expression in an invalid location. See
    https://lit.dev/docs/templates/expressions/#invalid-locations for more information about invalid expression
    locations.
  `;

  throw new Error(errorMsg);
}

const range = (value: string): number[] => {
  if (value.includes(',')) {
    return value.split(',').map(Number);
  }
  const match = value.match(/([\d.]+)(?:~)?([\d.]+)?(?::)?([\d.]+)?/);
  if (match) {
    const [, start = 1, end = start, step = 1] = match;
    const values = [];
    for (let n = Number(start); n <= Number(end); n += Number(step)) {
      values.push(n);
    }
    return values;
  } else {
    throw new Error(`Malformed range: '${value}`);
  }
};

export function stripUndefineds(obj: unknown) {
  if (Array.isArray(obj)) {
    for (const value of obj) {
      stripUndefineds(value);
    }
  } else if (isObj(obj)) {
    for (const prop in obj) {
      if (obj.hasOwnProperty(prop)) {
        const value = obj[prop];
        if (value === undefined) {
          delete obj[prop];
        } else {
          stripUndefineds(value);
        }
      }
    }
  }
}

private _sizeHostElement(size?: Size | null) {
  // Some browsers seem to crap out if the host element gets larger than
  // a certain size, so we clamp it here (this value based on ad hoc
  // testing in Chrome / Safari / Firefox Mac)
  const max = 8200000;
  const h = size && size.width !== null ? Math.min(max, size.width) : 0;
  const v = size && size.height !== null ? Math.min(max, size.height) : 0;

  if (this._isScroller) {
    this._getSizer().style.transform = `translate(${h}px, ${v}px)`;
  } else {
    const style = this._hostElement!.style;
    (style.minWidth as string | null) = h ? `${h}px` : '100%';
    (style.minHeight as string | null) = v ? `${v}px` : '100%';
  }
}

_getActiveItems() {
  const metrics = this._metrics!;
  const {rolumns} = metrics;
  if (rolumns === 0 || this._rangeMap.size === 0) {
    this._first = -1;
    this._last = -1;
    this._physicalMin = 0;
    this._physicalMax = 0;
  } else {
    const min = Math.max(0, this._scrollPosition - this._overhang);
    const max = Math.min(
      this._scrollSize,
      this._scrollPosition + this._viewDim1 + this._overhang
    );
    const maxIdx = this.items.length - 1;
    const minKey = this._getRangeMapKey(min, MIN);
    const maxKey = this._getRangeMapKey(max, MAX);
    let first = maxIdx;
    let last = 0;
    for (let n = minKey; n <= maxKey; n += this._RANGE_MAP_GRANULARITY) {
      const [rangeFirst, rangeLast] = this._rangeMap.get(n) ?? [maxIdx, 0];
      first = Math.min(first, rangeFirst);
      last = Math.max(last, rangeLast);
    }
    this._first = first;
    this._last = last;
  }
}

