private findTemplates(sourceFile: ts.SourceFile) {
  // Store the stack of open ancestor nodes from sourceFile to the current
  // node so that we can quickly get the top-level statement containing a
  // template.
  const nodeStack: Array<ts.Node> = [];

  const findTemplates = <T extends ts.Node>(node: T) => {
    return ts.visitNode(node, (node: ts.Node): ts.Node => {
      nodeStack.push(node);
      if (
        ts.isTaggedTemplateExpression(node) &&
        this.checker.isLitHtmlTaggedTemplateExpression(node)
      ) {
        const topStatement = nodeStack[1] as ts.Statement;
        const templateInfo = {
          topStatement,
          node,
          variableName: ts.factory.createUniqueName('lit_template'),
        };
        const templates =
          this.topLevelStatementToTemplate.get(topStatement) ?? [];
        templates.push(templateInfo);
        this.topLevelStatementToTemplate.set(topStatement, templates);
        this.expressionToTemplate.set(node, templateInfo);
      }
      const result = ts.visitEachChild(node, findTemplates, this.context);
      nodeStack.pop();
      return result;
    });
  };

  return findTemplates(sourceFile);
}

const isDirty = (value: unknown, previous: unknown) => {
  if (Array.isArray(value)) {
    // Dirty-check arrays by item
    if (
      Array.isArray(previous) &&
      previous.length === value.length &&
      value.every((v, i) => v === (previous as Array<unknown>)[i])
    ) {
      return false;
    }
  } else if (previous === value) {
    // Dirty-check non-arrays by identity
    return false;
  }
  return true;
};

private _handleScrollEvent() {
  if (this._benchmarkStart && 'mark' in window.performance) {
    try {
      window.performance.measure('uv-virtualizing', 'uv-start', 'uv-end');
    } catch (e) {
      console.warn('Error measuring performance data: ', e);
    }
    window.performance.mark('uv-start');
  }
  if (this._scrollerController!.correctingScrollError === false) {
    // This is a user-initiated scroll, so we unpin the layout
    this._layout?.unpin();
  }
  this._schedule(this._updateLayout);
}

_update(values: Array<unknown>) {
  let i = 0;
  for (const part of this._$parts) {
    if (part !== undefined) {
      debugLogEvent &&
        debugLogEvent({
          kind: 'set part',
          part,
          value: values[i],
          valueIndex: i,
          values,
          templateInstance: this,
        });
      if ((part as AttributePart).strings !== undefined) {
        (part as AttributePart)._$setValue(values, part as AttributePart, i);
        // The number of values the part consumes is part.strings.length - 1
        // since values are in between template spans. We increment i by 1
        // later in the loop, so increment it by part.strings.length - 2 here
        i += (part as AttributePart).strings!.length - 2;
      } else {
        part._$setValue(values[i]);
      }
    }
    i++;
  }
}

