async updateLayoutConfig(layoutConfig: LayoutConfigValue) {
  // If layout initialization hasn't finished yet, we wait
  // for it to finish so we can check whether the new config
  // is compatible with the existing layout before proceeding.
  await this._layoutInitialized;
  const Ctor =
    ((layoutConfig as LayoutSpecifier).type as LayoutConstructor) ||
    // The new config is compatible with the current layout,
    // so we update the config and return true to indicate
    // a successful update
    DefaultLayoutConstructor;
  if (typeof Ctor === 'function' && this._layout instanceof Ctor) {
    const config = {...(layoutConfig as LayoutSpecifier)} as {
      type?: LayoutConstructor;
    };
    delete config.type;
    this._layout.config = config as BaseLayoutConfig;
    // The new config requires a different layout altogether, but
    // to limit implementation complexity we don't support dynamically
    // changing the layout of an existing virtualizer instance.
    // Returning false here lets the caller know that they should
    // instead make a new virtualizer instance with the desired layout.
    return true;
  }
  return false;
}

export function property(options?: PropertyDeclaration): PropertyDecorator {
  return <C extends Interface<ReactiveElement>, V>(
    protoOrTarget:
      | object
      | ClassAccessorDecoratorTarget<C, V>
      | ((value: V) => void),
    nameOrContext:
      | PropertyKey
      | ClassAccessorDecoratorContext<C, V>
      | ClassSetterDecoratorContext<C, V>
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ): any => {
    return (
      typeof nameOrContext === 'object'
        ? standardProperty<C, V>(
            options,
            protoOrTarget as
              | ClassAccessorDecoratorTarget<C, V>
              | ((value: V) => void),
            nameOrContext as StandardPropertyContext<C, V>
          )
        : legacyProperty(
            options,
            protoOrTarget as Object,
            nameOrContext as PropertyKey
          )
    ) as PropertyDecorator;
  };
}

formResetCallback() {
  const classKey = getClassKey(this.constructor);

  // Restore the initial value
  const valueAccess = valueAccessors.get(classKey);
  const defaultValueAccess = defaultValueAccessors.get(classKey);

  valueAccess?.set(
    this,
    defaultValueAccess !== undefined
      ? defaultValueAccess.get(this)
      : initialValues.get(this)
  );

  // Restore the initial state
  const stateAccess = stateAccessors.get(classKey);
  const defaultStateAccess = defaultStateAccessors.get(classKey);

  stateAccess?.set?.(
    this,
    defaultStateAccess !== undefined
      ? defaultStateAccess.get(this)
      : (initialStates.get(this) ?? null)
  );
}

public fun <T : Throwable> exception(
    klass: KClass<T>,
    handler: suspend (call: ApplicationCall, T) -> Unit
) {
    @Suppress("UNCHECKED_CAST")
    val cast = handler as suspend (ApplicationCall, Throwable) -> Unit

    exceptions[klass] = cast
}

private fun HttpCache.findAndRefresh(request: HttpRequest, response: HttpResponse): HttpResponse? {
    val url = response.call.request.url
    val cacheControl = response.cacheControl()

    val storage = if (CacheControl.PRIVATE in cacheControl) privateStorage else publicStorage

    val cache = storage.selectResponseToUpdate(response, url, request) ?: return null
    val newVaryKeys = response.varyKeys().ifEmpty { cache.varyKeys }
    val mergedHeaders = cache.responseHeaders.merge(response.headers)
    val expires = response.cacheExpires(isSharedClient)
    val updatedCache = cache.withFreshenedMetadata(expires, newVaryKeys, mergedHeaders)

    if (cache.varyKeys != newVaryKeys && storage is UnlimitedCacheStorage) {
        storage.remove(url, cache.varyKeys)
    }
    storage.store(url, updatedCache)
    return updatedCache.produceResponse()
}

override fun release() {
    headers.invokeOnCompletion { t ->
        if (t == null) {
            headers.getCompleted().release()
        }
    }

    body.discardBlocking()
}

override fun onFillable() {
    val handler = currentHandler.getAndSet(null) ?: return
    buffer.flip()
    val count = try {
        endPoint.fill(buffer)
    } catch (cause: Throwable) {
        handler.resumeWithException(ClosedChannelException())
    }

    if (count == -1) {
        handler.resumeWithException(ClosedChannelException())
    } else {
        handler.resume(Unit)
    }
}

