public fun insertPhaseAfter(reference: PipelinePhase, phase: PipelinePhase) {
    if (hasPhase(phase)) return

    val index = findPhaseIndex(reference)
    if (index == -1) {
        throw InvalidPhaseException("Phase $reference was not registered for this pipeline")
    }
    // insert after the last phase that has Relation.After on [reference]
    var lastRelatedPhaseIndex = index
    for (i in index + 1..phasesRaw.lastIndex) {
        val relation = (phasesRaw[i] as? PhaseContent<*, *>)?.relation ?: break
        val relatedTo = (relation as? PipelinePhaseRelation.After)?.relativeTo ?: continue
        lastRelatedPhaseIndex = if (relatedTo == reference) i else lastRelatedPhaseIndex
    }

    phasesRaw.add(
        lastRelatedPhaseIndex + 1,
        PhaseContent<TSubject, TContext>(phase, PipelinePhaseRelation.After(reference))
    )
}

private fun verifyHello(serverHello: TLSServerHello) {
    val suite = serverHello.cipherSuite
    check(suite in config.cipherSuites) { "Unsupported cipher suite ${suite.name} in SERVER_HELLO" }

    val clientExchanges = SupportedSignatureAlgorithms.filter {
        it.hash == suite.hash && it.sign == suite.signatureAlgorithm
    }

    if (clientExchanges.isEmpty()) {
        throw TLSException("No appropriate hash algorithm for suite: $suite")
    }

    val serverExchanges = serverHello.hashAndSignAlgorithms
    if (serverExchanges.isEmpty()) return

    if (!clientExchanges.any { it in serverExchanges }) {
        val message = "No sign algorithms in common. \n" +
            "Server candidates: $serverExchanges \n" +
            "Client candidates: $clientExchanges"

        throw TLSException(message)
    }
}

public fun ContentType.Companion.fromFilePath(path: String): List<ContentType> {
    val slashIndex = path.lastIndexOfAny("/\\".toCharArray())
    val index = path.indexOf('.', startIndex = slashIndex + 1)
    if (index == -1) {
        return emptyList()
    }
    return fromFileExtension(path.substring(index + 1))
}

private fun insertRelativePhase(fromPhaseOrContent: Any, fromPhase: PipelinePhase): Boolean {
    val fromPhaseRelation = when {
        fromPhaseOrContent === fromPhase -> PipelinePhaseRelation.Last
        else -> (fromPhaseOrContent as PhaseContent<*, *>).relation
    }

    when (fromPhaseRelation) {
        is PipelinePhaseRelation.Last -> addPhase(fromPhase)

        is PipelinePhaseRelation.Before if hasPhase(fromPhaseRelation.relativeTo) ->
            insertPhaseBefore(fromPhaseRelation.relativeTo, fromPhase)

        is PipelinePhaseRelation.After -> insertPhaseAfter(fromPhaseRelation.relativeTo, fromPhase)

        else -> return false
    }
    return true
}

