public fun mergePhases(from: Pipeline<TSubject, TContext>) {
    val fromPhases = from.phasesRaw
    val toInsert = fromPhases.toMutableList()
    // the worst case is O(n^2), but it will happen only
    // when all phases were inserted before each other into the second pipeline
    // (see test testDependantPhasesLastCommon).
    // in practice, it will be linear time for most cases
    while (toInsert.isNotEmpty()) {
        val iterator = toInsert.iterator()
        while (iterator.hasNext()) {
            val fromPhaseOrContent = iterator.next()

            val fromPhase = (fromPhaseOrContent as? PipelinePhase)
                ?: (fromPhaseOrContent as PhaseContent<*, *>).phase

            if (hasPhase(fromPhase)) {
                iterator.remove()
            } else {
                val inserted = insertRelativePhase(fromPhaseOrContent, fromPhase)
                if (inserted) {
                    iterator.remove()
                }
            }
        }
    }
}

override fun tryEvaluate(context: RoutingResolveContext, segmentIndex: Int): RouteSelectorEvaluation {
    val requestHost = context.call.request.origin.serverHost
    val requestPort = context.call.request.origin.serverPort

    if (hostList.isNotEmpty() || hostPatterns.isNotEmpty()) {
        val matches1 = requestHost in hostList
        val matches2 = !matches1 && hostPatterns.any { it.matches(requestHost) }

        if (!matches1 && !matches2) {
            return RouteSelectorEvaluation.Failed
        }
    }

    if (portsList.isNotEmpty()) {
        if (requestPort !in portsList) return RouteSelectorEvaluation.Failed
    }

    val params = Parameters.build {
        append(HostNameParameter, requestHost)
        append(PortParameter, requestPort.toString())
    }

    return RouteSelectorEvaluation.Success(RouteSelectorEvaluation.qualityConstant, params)
}

