pub async fn remove_track(&self, track: Arc<MediaStreamTrack>) -> Result<(), RtcError> {
    let senders = self.inner.get_senders().await;
    for sender in senders {
        if let Some(sender_track) = sender.track().await {
            if sender_track.id() != track.id() {
                continue;
            }
            return self
                .inner
                .remove_track(&sender)
                .await
                .map_err(|e| RemoveTrackError(e.to_string()));
        }
    }
    Err(RemoveTrackError("Track not found".to_string()))
}

pub async fn read_rtp(&self) -> Result<(), RtcError> {
    let track = self.as_remote()?;
    if !self.enabled() {
        return Ok(());
    }
    let (rtp_packet, _) = {
        let _ = self
            .read_mutex
            .try_lock()
            .map_err(|_| MediaTrackError("Parallel read is not allowed".to_string()))?;
        track
            .read_rtp()
            .await
            .map_err(|e| MediaTrackError(e.to_string()))?
    };
    if let Some(wrapper) = self.sink_wrapper.load_full() {
        wrapper.sink.write_rtp(rtp_packet).await?;
    }
    Ok(())
}

