mutating func _createSpace(before index: Int, requiredSpace: Int) {
    precondition(index >= self.readerIndex)
    let bytesToMove = self.writerIndex - index

    // Add the required number of bytes to the end first
    self.writeRepeatingByte(0, count: requiredSpace)
    // Move the data forward by that many bytes, to make space at the front
    // The precondition above makes this safe: our indices are in the valid range, so we can safely use them here
    try! self.copyBytes(at: index, to: index + requiredSpace, length: bytesToMove)
}

private func runWithoutCoWs() -> Int {
    for _ in 0..<self.runCount {
        // To avoid CoWs this has to be a new buffer every time. This is expensive, sadly, so tests using this strategy
        // must do fewer iterations.
        let data = self.channel.allocator.buffer(size: self.dataSize, dataStrategy: self.dataStrategy)
        let frame = WebSocketFrame(opcode: .binary, maskKey: self.maskingKey, data: data, extensionData: nil)
        self.channel.write(frame, promise: nil)
    }
    return 1
}

private func run(_ task: UnderlyingTask) {
    // for macOS: in case any calls we make to Foundation put objects into an autoreleasepool
    withAutoReleasePool {
        switch task {
        case .function(let function):
            function()
        case .unownedJob(let erasedUnownedJob):
            if #available(macOS 14.0, iOS 17.0, watchOS 10.0, tvOS 17.0, *) {
                erasedUnownedJob.unownedJob.runSynchronously(on: self.asUnownedSerialExecutor())
            } else {
                fatalError("Tried to run an UnownedJob without runtime support")
            }
        case .callback(let handler):
            handler.handleScheduledCallback(eventLoop: self)
        }
    }
}

static func create(iovectorCount: Int) -> Self {
    let head = PooledBufferHead(iovectorCount: iovectorCount)

    let baseStorage = Self.create(minimumCapacity: head.totalByteCount) { _ in
        head
    }

    // Here we set up our memory bindings.

    // Intentionally using a force cast here to avoid a miss compiliation in 5.10.
    // This is as fast as an unsafeDownCast since ManagedBuffer is inlined and the optimizer
    // can eliminate the upcast/downcast pair
    let storage = baseStorage as! Self
    storage.withUnsafeMutablePointers { headPointer, tailPointer in
        UnsafeRawPointer(tailPointer + headPointer.pointee.iovectorOffset).bindMemory(
            to: IOVector.self,
            capacity: iovectorCount
        )
        UnsafeRawPointer(tailPointer + headPointer.pointee.bufferOwnersOffset).bindMemory(
            to: Unmanaged<AnyObject>.self,
            capacity: iovectorCount
        )
        UnsafeRawPointer(tailPointer + headPointer.pointee.memorySentinelOffset).bindMemory(
            to: MemorySentinel.self,
            capacity: 1
