    let promise: EventLoopPromise<T> = self.makePromise()
    let (task, scheduled) = self._prepareToSchedule(deadline: deadline, promise: promise, task: task)

    do {
        try self._scheduleIsolated0(.scheduled(task))
    } catch {
        promise.fail(error)
    }

    return scheduled
}

func initialiseState0() throws {
    try ring.io_uring_queue_init()
    self.selectorFD = ring.fd

    // eventfd are always singleshot and re-register each time around
    // as certain use cases of nio seems to generate superfluous wakeups.
    // (at least its tested for that in some of the performance tests
    // e.g. future_whenallsucceed_100k_deferred_off_loop, future_whenallcomplete_100k_deferred_off_loop
    // ) - if using normal ET multishots, we would get 100k events to handle basically.
    // so using single shot for wakeups makes those tests run 30-35% faster approx.

    self.eventFD = try EventFd.eventfd(initval: 0, flags: Int32(EventFd.EFD_CLOEXEC | EventFd.EFD_NONBLOCK))

    ring.io_uring_prep_poll_add(
        fileDescriptor: self.eventFD,
        pollMask: URing.POLLIN,
        registrationID: SelectorRegistrationID(rawValue: 0),
        multishot: false
    )  // wakeups

    self.lifecycleState = .open
    _debugPrint("URingSelector up and running fd [\(self.selectorFD)] wakeups on event_fd [\(self.eventFD)]")
}

public mutating func writeLengthPrefixedString<
    Strategy: NIOBinaryIntegerEncodingStrategy
>(
    _ string: String,
    strategy: Strategy
) -> Int {
    // writeString always writes the String as UTF8 bytes, without a null-terminator
    // So the length will be the utf8 count
    self.reserveCapacity(minimumWritableBytes: string.utf8.count + strategy.requiredBytesHint)
    var written = 0
    written += self.writeEncodedInteger(string.utf8.count, strategy: strategy)
    written += self.writeString(string)
    return written
}

internal func _withPlatformString<Result>(
    _ body: (UnsafePointer<CInterop.PlatformChar>) throws -> Result
) rethrows -> Result {
    // Need to #if because CChar may be signed
    #if os(Windows)
    return try self.withCString(encodedAs: UTF16.self, body)
    #else
    return try withCString(body)
    #endif
}

internal func syncFinaliseClose(joinThread: Bool) {
    // This may not be true in the future but today we need to join all ELs that can't be shut down individually.
    assert(joinThread != self.canBeShutdownIndividually)
    let goAhead = self.externalStateLock.withLock { () -> Bool in
        switch self.externalState {
        case .closed:
            self.externalState = .reclaimingResources
            return true
        case .resourcesReclaimed, .reclaimingResources:
            return false
        default:
            preconditionFailure("illegal lifecycle state in syncFinaliseClose: \(self.externalState)")
        }
    }
    guard goAhead else {
        return
    }
    if joinThread {
        self.thread.join()
    }
    self.externalStateLock.withLock {
        precondition(self.externalState == .reclaimingResources)
        self.externalState = .resourcesReclaimed
    }
}

private func createDirectory(
    at path: FilePath,
    withIntermediateDirectories createIntermediateDirectories: Bool,
    permissions: FilePermissions?,
    idempotent: Bool
) async throws {
    try await self.threadPool.runIfActive {
        try self._createDirectory(
            at: path,
            withIntermediateDirectories: createIntermediateDirectories,
            permissions: permissions ?? .defaultsForDirectory,
            idempotent: idempotent
        ).get()
    }
}
